   mcq('كيف تُعرف السخرية من الغضب؟', ['لا فرق', 'الغاضب يقول ما يريد مباشرة بصوت مرتفع، والساخر يقول ضدّ ما يريد بهدوء ويستعمل كلمة خصمه', 'الساخر يصرخ'], 1, 'الكلمة الكاشفة عند فاطمة «وفّرتُ»، كلمة الدراسة نفسها على شيء خسرته.'),
   mcq('ما العلامات الثلاث التي تُعرف بها النبرة إن لم يذكرها الكاتب؟', ['الطول والعنوان والصورة', 'الصفات والمبالغة، وألفاظ التحوّط والشرط، وتكرار كلمة الخصم بمعنى معكوس', 'الأرقام فقط'], 1, 'والمحايد تغيب عنه الثلاث: رقم ومصدر وفعل محايد، كما في نشرة المذيعة.'),
   match('الدرجة وفعلها', [('محايدة', 'قال · ذكر · أفاد'), ('واثقة', 'أكّد · شدّد على · أوضح'), ('شاكّة', 'زعم · ادّعى · قيل إنّ'), ('موجَّهة', 'حذّر من · نفى · أقرّ بـ · تساءل')]),
   match('النبرة وعلامتها', [('متحمّسة', 'صفات ومبالغة: رائع، أبدًا'), ('متحفّظة', 'تحوّط وشرط: ربّما، إلى حدّ ما، لم أقرّر'), ('ساخرة', 'تكرار كلمة الخصم بمعنى معكوس'), ('محايدة', 'رقم ومصدر وفعل محايد')]),
   match('الخطأ وإصلاحه', [('زعم الدكتور طارق', 'أكّد أو قال، لأنّ لا دليل على الشكّ'), ('ارتفعت الإنتاجية، ووقف', 'بحسب الدراسة ارتفعت الإنتاجية'), ('يبدو أنّ الدراسة شملت ألفين وأربعمئة', 'شملت الدراسة ألفين وأربعمئة'), ('فاطمة غاضبة', 'فاطمة ساخرة بهدوء')]),
   order('رتّب الجملة بالإسناد', ['بحسب', 'الدراسة،', 'ارتفعت', 'الإنتاجية', 'سبعة', 'في', 'المئة.']),
   order('رتّب الجملة المعترضة', ['الإنتاجية،', 'كما', 'تقول', 'الدراسة،', 'ارتفعت.']),
   order('رتّب قاعدة هند', ['تحوّط', 'لما', 'لم', 'تتحقّق', 'منه،', 'وأثبت', 'ما', 'تحقّقتَ', 'منه.']),
   pic('من الدرس: «ليلى تكتب الأعمدة الثلاثة على السبّورة»', ['teacher', 'nurse', 'officer'], 0),
