   cloze('أكمل التحوّط', 'ألفاظ التحوّط للخبر غير المؤكَّد: ___ أنّ، ومن ___ أن، و___، وإلى حدّ ما.', ['يبدو', 'المرجّح', 'قد'], ['أكّد', 'المؤكَّد', 'لن']),
   cloze('أكمل أقرّ وتساءل', '___ أبو محمد بأنّ التجربة أقصر من أن يُحكم عليها، و___ سامي عمّن سيفتح الباب، و___ الدكتور طارق من تقليد الشركات الكبيرة.', ['أقرّ', 'تساءل', 'حذّر'], ['زعم', 'أكّد', 'نفى']),
   cloze('أكمل علامات النبرة', 'الصفات و___ للحماسة، وألفاظ ___ والشرط للتحفّظ، وتكرار كلمة ___ بمعنى معكوس للسخرية.', ['المبالغة', 'التحوّط', 'الخصم'], ['الأرقام', 'النقل', 'الكاتب']),
   tf('قالت هند إنّ «قيل إنّ» تُستعمل حين لا نعرف المصدر ولا نستطيع التحقّق.', 'هند: «قيل إنّ» أو «ذكر أحد الحاضرين»، ولا تقولي زعم إلّا إن كنتِ تملكين ما يكذّبه.', 'true', 'الشكّ المعلَن يحتاج إلى دليل، أمّا الجهل بالمصدر فله قيل إنّ.'),
   tf('ما بعد «أنّ» في «أفادت الدراسة أنّ الإنتاجية ارتفعت» مرفوع.', 'هند: الثلاث صحيحة، وانتبهي إلى أنّ ما بعد أنّ منصوب: الإنتاجيةَ.', 'false', 'اسم أنّ منصوب.'),
   tf('سيصحّح فهد واجب الطلّاب في الاستوديو.', 'هند: الواجب: خذوا خبرًا واحدًا، وانقلوه أربع مرّات بأربعة أفعال نقل.', 'ng', 'ذُكر الواجب ولم يُذكر من يصحّحه ولا أين.'),
