   dic('أكّد الدكتور طارق أنّ الرقم لا يكفي وحده.', ['أكد الدكتور طارق أن الرقم لا يكفي وحده']),
   dic('لا تقل زعم إلّا بدليل.', ['لا تقل زعم إلا بدليل']),
