   order('رتّب افتتاح الاعتراض', ['أتّفق', 'معكِ', 'في', 'أنّ', 'التقرير', 'أُغلق', 'قبل', 'موعده.']),
   order('رتّب الردّ', ['هذا', 'صحيح', 'من', 'جهة،', 'لكن', 'من', 'جهة', 'أخرى.']),
