   cloze('أكمل المداخلة', 'أنا ضدّ ___ لا ضدّه، و___ من الدراسة نفسها: الشركات الصغيرة استفادت ___.', ['تعميمه', 'الدليل', 'أقلّ'], ['الجميع', 'الشرط', 'أكثر']),
